import React, { useState } from "react";
import { useDispatch, useSelector } from "react-redux";
import { markComplete, deleteTask } from "../State/action-creators/index";
import completeIcon from "./assets/CheckCircle.png";
import updateIcon from "./assets/Group 127.png"
import deleteIcon from "./assets/Group 130.png"
import "../Style/DisplayAllTasks.css";

function DisplayAllTasks() {
  const dispatch = useDispatch();
  const tasks = useSelector((state) => state.tasks);
  const [searchCategory, setSearchCategory] = useState("");
  const [searchPriorty, setSearchPriorty] = useState("");
  const [searchName, setSearchName] = useState("");
  return (
    <>
      <div className="SearchForm">
        <div className="SearchbyCategory">
          <select
            className="Categoryselect-box"
            value={searchCategory}
            onChange={(e) => setSearchCategory(e.target.value)}
          >
            <option value="">By Catagory</option>
            <option value="Learning/working">Learning/working</option>
            <option value="Playing">Playing</option>
            <option value="eating">Eating</option>
          </select>
        </div>
        <div className="SearchbyPriorty">
          <select
            className="Priortyselect-box"
            value={searchPriorty}
            onChange={(e) => setSearchPriorty(e.target.value)}
          >
            <option value="">By Priorty</option>
            <option value="Low">Low</option>
            <option value="Mid">Mid</option>
            <option value="High">High</option>
          </select>
        </div>
        <div>
          <input
            className="SearchbyTitle"
            type="text"
            name="title"
            value={searchName}
            onChange={(e) => setSearchName(e.target.value)}
            placeholder="Search by Title"
          />
        </div>
      </div>
      <div className="card-container">
        {tasks.length === 0 ? (
          <p>No tasks yet!</p>
        ) : (
          tasks.map((task) => (
            <div className="task-card">
               <div className="task-info">
              <h3>{task.title}</h3>
              <p className="description">{task.description}</p>
              <p className="date">Start date : {task.startDate}</p>
              </div>
              <div className="icons">
                <div className="task-actions">
                  <button
                    className="btn complete"
                    onClick={() => dispatch(markComplete(task.id))}
                  >
                    <img src={completeIcon}></img>
                  </button>
                  <button className="btn edit"><img src={updateIcon}></img></button>
                  <button
                    className="btn delete"
                    onClick={() => dispatch(deleteTask(task.id))}
                  >
                    <img src={deleteIcon}></img>
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </>
  );
}

export default DisplayAllTasks;
